     1	//! Pure-Rust port of `mapbox::earcut` (the `earcut.hpp` header-only library).
     2	//!
     3	//! Layout mirrors the C++ header:
     4	//!
     5	//! * [`node`] – the `Node` struct and its arena
     6	//! * [`geom`] – scalar geometry helpers (`area`, `sign`, `pointInTriangle`, …)
     7	//! * [`predicates`] – node-level predicates (`intersects`, `locallyInside`, …)
     8	//! * [`zorder`] – the z-order curve hash (`zOrder`, `indexCurve`, `sortLinked`)
     9	//! * [`triangulate`] – the ear-clipping core and its recovery passes
    10	//! * [`holes`] – hole elimination via bridge diagonals
    11	//!
    12	//! The entry point is [`earcut`].
    13	
    14	pub mod geom;
    15	pub mod holes;
    16	pub mod node;
    17	pub mod predicates;
    18	pub mod triangulate;
    19	pub mod zorder;
    20	
    21	use self::node::{Arena, NULL};
    22	
    23	/// Triangulate a polygon given as a list of rings (outer ring first, holes
    24	/// after) and return a flat list of triangle vertex indices.
    25	///
    26	/// Indices refer to the concatenation of all rings, in the order given.
    27	pub fn earcut(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
    28	    let mut state = Earcut::new();
    29	    state.run(polygon);
    30	    state.indices
    31	}
    32	
    33	/// Triangulator state — the C++ `detail::Earcut<N>` class.
    34	pub struct Earcut {
    35	    pub nodes: Arena,
    36	    pub indices: Vec<u32>,
    37	    pub vertices: usize,
    38	
    39	    pub hashing: bool,
    40	    pub min_x: f64,
    41	    pub max_x: f64,
    42	    pub min_y: f64,
    43	    pub max_y: f64,
    44	    pub inv_size: f64,
    45	}
    46	
    47	impl Default for Earcut {
    48	    fn default() -> Self {
    49	        Self::new()
    50	    }
    51	}
    52	
    53	impl Earcut {
    54	    pub fn new() -> Self {
    55	        Earcut {
    56	            nodes: Arena::new(),
    57	            indices: Vec::new(),
    58	            vertices: 0,
    59	            hashing: false,
    60	            min_x: 0.0,
    61	            max_x: 0.0,
    62	            min_y: 0.0,
    63	            max_y: 0.0,
    64	            inv_size: 0.0,
    65	        }
    66	    }
    67	
    68	    /// `Earcut<N>::operator()(const Polygon& points)`.
    69	    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
    70	        self.indices.clear();
    71	        self.vertices = 0;
    72	
    73	        if points.is_empty() {
    74	            return;
    75	        }
    76	
    77	        // The shape is considered "simple" while the running vertex budget of
    78	        // 80 has not been exhausted; once it goes negative we switch on the
    79	        // z-order hash. Note the loop stops early, exactly as in C++, so `len`
    80	        // is only a lower bound on the true vertex count.
    81	        let mut threshold: i32 = 80;
    82	        let mut len: usize = 0;
    83	        let mut ring = 0usize;
    84	        while threshold >= 0 && ring < points.len() {
    85	            threshold -= points[ring].len() as i32;
    86	            len += points[ring].len();
    87	            ring += 1;
    88	        }
    89	
    90	        // Estimate the size of the node arena, as the C++ pool does.
    91	        self.nodes.reserve(len * 3 / 2);
    92	        self.indices.reserve(len + points[0].len());
    93	
    94	        let mut outer_node = self.linked_list(&points[0], true);
    95	        if outer_node == NULL || self.nodes[outer_node].prev == self.nodes[outer_node].next {
    96	            return;
    97	        }
    98	
    99	        if points.len() > 1 {
   100	            outer_node = self.eliminate_holes(points, outer_node);
   101	        }
   102	
   103	        self.hashing = threshold < 0;
   104	        if self.hashing {
   105	            self.compute_bbox(outer_node);
   106	        }
   107	
   108	        self.earcut_linked(outer_node, 0);
   109	
   110	        self.nodes.clear();
   111	    }
   112	
   113	    /// Polygon bounding box plus the `inv_size` scale used by [`zorder`].
   114	    fn compute_bbox(&mut self, outer_node: usize) {
   115	        self.min_x = self.nodes[outer_node].x;
   116	        self.max_x = self.min_x;
   117	        self.min_y = self.nodes[outer_node].y;
   118	        self.max_y = self.min_y;
   119	
   120	        let mut p = self.nodes[outer_node].next;
   121	        loop {
   122	            let x = self.nodes[p].x;
   123	            let y = self.nodes[p].y;
   124	            self.min_x = geom::fmin(self.min_x, x);
   125	            self.min_y = geom::fmin(self.min_y, y);
   126	            self.max_x = geom::fmax(self.max_x, x);
   127	            self.max_y = geom::fmax(self.max_y, y);
   128	            p = self.nodes[p].next;
   129	            if p == outer_node {
   130	                break;
   131	            }
   132	        }
   133	
   134	        // minX, minY and inv_size transform coords into the 15-bit integer
   135	        // range the z-order curve works in.
   136	        let size = geom::fmax(self.max_x - self.min_x, self.max_y - self.min_y);
   137	        self.inv_size = if size != 0.0 { 32767.0 / size } else { 0.0 };
   138	    }
   139	}
