     1	//! Arena-backed node storage for the triangulator.
     2	//!
     3	//! The C++ original threads raw `Node*` pointers through every routine and
     4	//! relies on pointer identity for loop termination. We keep the same shape by
     5	//! storing nodes in a flat arena and using `usize` handles, with [`NULL`]
     6	//! standing in for `nullptr`.
     7	
     8	/// Sentinel handle standing in for C++'s `nullptr`.
     9	pub const NULL: usize = usize::MAX;
    10	
    11	/// A vertex in a circular doubly-linked polygon ring.
    12	#[derive(Clone, Debug)]
    13	pub struct Node {
    14	    /// Index of this vertex in the caller's flattened vertex list.
    15	    pub i: u32,
    16	    pub x: f64,
    17	    pub y: f64,
    18	
    19	    /// Previous / next vertex in the polygon ring.
    20	    pub prev: usize,
    21	    pub next: usize,
    22	
    23	    /// Z-order curve value.
    24	    pub z: i32,
    25	
    26	    /// Previous / next node in z-order.
    27	    pub prev_z: usize,
    28	    pub next_z: usize,
    29	
    30	    /// Whether this is a Steiner point.
    31	    pub steiner: bool,
    32	}
    33	
    34	/// Flat arena of [`Node`]s. Handles stay valid for the lifetime of a
    35	/// triangulation, which matters because the C++ code holds "pointers" across
    36	/// allocations of new nodes (`split_polygon`).
    37	#[derive(Default)]
    38	pub struct Arena {
    39	    nodes: Vec<Node>,
    40	}
    41	
    42	impl Arena {
    43	    pub fn new() -> Self {
    44	        Arena { nodes: Vec::new() }
    45	    }
    46	
    47	    pub fn reserve(&mut self, additional: usize) {
    48	        self.nodes.reserve(additional);
    49	    }
    50	
    51	    pub fn clear(&mut self) {
    52	        self.nodes.clear();
    53	    }
    54	
    55	    pub fn len(&self) -> usize {
    56	        self.nodes.len()
    57	    }
    58	
    59	    pub fn is_empty(&self) -> bool {
    60	        self.nodes.is_empty()
    61	    }
    62	
    63	    /// Equivalent of the C++ `nodes.construct(i, x, y)`.
    64	    pub fn construct(&mut self, i: u32, x: f64, y: f64) -> usize {
    65	        self.nodes.push(Node {
    66	            i,
    67	            x,
    68	            y,
    69	            prev: NULL,
    70	            next: NULL,
    71	            z: 0,
    72	            prev_z: NULL,
    73	            next_z: NULL,
    74	            steiner: false,
    75	        });
    76	        self.nodes.len() - 1
    77	    }
    78	}
    79	
    80	impl std::ops::Index<usize> for Arena {
    81	    type Output = Node;
    82	
    83	    #[inline]
    84	    fn index(&self, idx: usize) -> &Node {
    85	        &self.nodes[idx]
    86	    }
    87	}
    88	
    89	impl std::ops::IndexMut<usize> for Arena {
    90	    #[inline]
    91	    fn index_mut(&mut self, idx: usize) -> &mut Node {
    92	        &mut self.nodes[idx]
    93	    }
    94	}
=== src/earcut/geom.rs ===
     1	//! Scalar helpers used throughout the triangulator.
     2	//!
     3	//! These mirror the free-standing arithmetic of the C++ header exactly,
     4	//! including comparison operators — the ear test is sign-sensitive, so `>=`
     5	//! versus `>` changes the emitted triangulation.
     6	
     7	/// `(0 < val) - (val < 0)`, the C++ `sign` helper.
     8	#[inline]
     9	pub fn sign(val: f64) -> i32 {
    10	    i32::from(0.0 < val) - i32::from(val < 0.0)
    11	}
    12	
    13	/// `std::min<double>` — returns `b` only when `b < a`, matching C++ ordering
    14	/// semantics (and therefore its NaN behaviour) rather than `f64::min`.
    15	#[inline]
    16	pub fn fmin(a: f64, b: f64) -> f64 {
    17	    if b < a {
    18	        b
    19	    } else {
    20	        a
    21	    }
    22	}
    23	
    24	/// `std::max<double>` — returns `b` only when `a < b`.
    25	#[inline]
    26	pub fn fmax(a: f64, b: f64) -> f64 {
    27	    if a < b {
    28	        b
    29	    } else {
    30	        a
    31	    }
    32	}
    33	
    34	/// Signed area of the triangle `p q r`, doubled. Negative means convex under
    35	/// earcut's winding convention.
    36	#[inline]
    37	pub fn area_xy(px: f64, py: f64, qx: f64, qy: f64, rx: f64, ry: f64) -> f64 {
    38	    (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
    39	}
    40	
    41	/// Is `p` inside (or on the boundary of) triangle `a b c`?
    42	#[inline]
    43	#[allow(clippy::too_many_arguments)]
    44	pub fn point_in_triangle(
    45	    ax: f64,
    46	    ay: f64,
    47	    bx: f64,
    48	    by: f64,
    49	    cx: f64,
    50	    cy: f64,
    51	    px: f64,
    52	    py: f64,
    53	) -> bool {
    54	    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
    55	        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
    56	        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
    57	}

=== src/earcut/predicates.rs ===
     1	//! Node-level geometric predicates — the C++ member functions that take
     2	//! `Node*` arguments.
     3	
     4	use super::geom::{area_xy, fmax, fmin, sign};
     5	use super::Earcut;
     6	
     7	impl Earcut {
     8	    /// Doubled signed area of the triangle `p q r`.
     9	    #[inline]
    10	    pub fn area(&self, p: usize, q: usize, r: usize) -> f64 {
    11	        let n = &self.nodes;
    12	        area_xy(n[p].x, n[p].y, n[q].x, n[q].y, n[r].x, n[r].y)
    13	    }
    14	
    15	    /// Exact coordinate equality (not an epsilon comparison — earcut relies on
    16	    /// bit equality here).
    17	    #[inline]
    18	    pub fn equals(&self, p1: usize, p2: usize) -> bool {
    19	        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    20	    }
    21	
    22	    /// Do segments `p1q1` and `p2q2` intersect, including collinear touching?
    23	    pub fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
    24	        let o1 = sign(self.area(p1, q1, p2));
    25	        let o2 = sign(self.area(p1, q1, q2));
    26	        let o3 = sign(self.area(p2, q2, p1));
    27	        let o4 = sign(self.area(p2, q2, q1));
    28	
    29	        if o1 != o2 && o3 != o4 {
    30	            return true; // general case
    31	        }
    32	
    33	        // Collinear special cases.
    34	        if o1 == 0 && self.on_segment(p1, p2, q1) {
    35	            return true;
    36	        }
    37	        if o2 == 0 && self.on_segment(p1, q2, q1) {
    38	            return true;
    39	        }
    40	        if o3 == 0 && self.on_segment(p2, p1, q2) {
    41	            return true;
    42	        }
    43	        if o4 == 0 && self.on_segment(p2, q1, q2) {
    44	            return true;
    45	        }
    46	
    47	        false
    48	    }
    49	
    50	    /// For collinear `p`, `q`, `r`: does `q` lie within the bounding box of
    51	    /// segment `pr`?
    52	    pub fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
    53	        let n = &self.nodes;
    54	        n[q].x <= fmax(n[p].x, n[r].x)
    55	            && n[q].x >= fmin(n[p].x, n[r].x)
    56	            && n[q].y <= fmax(n[p].y, n[r].y)
    57	            && n[q].y >= fmin(n[p].y, n[r].y)
    58	    }
    59	
    60	    /// Does the diagonal `ab` cross any polygon edge?
    61	    pub fn intersects_polygon(&self, a: usize, b: usize) -> bool {
    62	        let mut p = a;
    63	        loop {
    64	            let pn = self.nodes[p].next;
    65	            if self.nodes[p].i != self.nodes[a].i
    66	                && self.nodes[pn].i != self.nodes[a].i
    67	                && self.nodes[p].i != self.nodes[b].i
    68	                && self.nodes[pn].i != self.nodes[b].i
    69	                && self.intersects(p, pn, a, b)
    70	            {
    71	                return true;
    72	            }
    73	            p = pn;
    74	            if p == a {
    75	                return false;
    76	            }
    77	        }
    78	    }
    79	
    80	    /// Does the diagonal `ab` lie inside the polygon's sector at `a`?
    81	    pub fn locally_inside(&self, a: usize, b: usize) -> bool {
    82	        let ap = self.nodes[a].prev;
    83	        let an = self.nodes[a].next;
    84	        if self.area(ap, a, an) < 0.0 {
    85	            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
    86	        } else {
    87	            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
    88	        }
    89	    }
    90	
    91	    /// Does the midpoint of `ab` fall inside the polygon? (Even-odd ray cast.)
    92	    pub fn middle_inside(&self, a: usize, b: usize) -> bool {
    93	        let mut inside = false;
    94	        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
    95	        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
    96	
    97	        let mut p = a;
    98	        loop {
    99	            let pn = self.nodes[p].next;
   100	            let (pxx, pyy) = (self.nodes[p].x, self.nodes[p].y);
   101	            let (nxx, nyy) = (self.nodes[pn].x, self.nodes[pn].y);
   102	            if ((pyy > py) != (nyy > py))
   103	                && nyy != pyy
   104	                && (px < (nxx - pxx) * (py - pyy) / (nyy - pyy) + pxx)
   105	            {
   106	                inside = !inside;
   107	            }
   108	            p = pn;
   109	            if p == a {
   110	                return inside;
   111	            }
   112	        }
   113	    }
   114	
   115	    /// Can `ab` be used to split the polygon in two?
   116	    pub fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
   117	        let an = self.nodes[a].next;
   118	        let ap = self.nodes[a].prev;
   119	        let bn = self.nodes[b].next;
   120	        let bp = self.nodes[b].prev;
   121	
   122	        self.nodes[an].i != self.nodes[b].i
   123	            && self.nodes[ap].i != self.nodes[b].i
   124	            // doesn't intersect other edges
   125	            && !self.intersects_polygon(a, b)
   126	            && ((self.locally_inside(a, b)
   127	                && self.locally_inside(b, a)
   128	                && self.middle_inside(a, b)
   129	                // does not create opposite-facing sectors
   130	                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
   131	                // special zero-length case
   132	                || (self.equals(a, b)
   133	                    && self.area(ap, a, an) > 0.0
   134	                    && self.area(bp, b, bn) > 0.0))
   135	    }
   136	
   137	    /// Whether sector `m` fully contains sector `p`.
   138	    pub fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
   139	        let mp = self.nodes[m].prev;
   140	        let mn = self.nodes[m].next;
   141	        let pp = self.nodes[p].prev;
   142	        let pn = self.nodes[p].next;
   143	        self.area(mp, m, pp) < 0.0 && self.area(pn, m, mn) < 0.0
   144	    }
   145	}
