     1	//! Z-order (Morton) curve hashing used to speed up the ear test on larger
     2	//! polygons.
     3	//!
     4	//! `earcut.hpp` switches this on once the input exceeds 80 vertices, so both
     5	//! the plain and the hashed ear tests have to be bit-faithful.
     6	
     7	use super::node::NULL;
     8	use super::Earcut;
     9	
    10	impl Earcut {
    11	    /// Interleave the coordinates of `(x_, y_)` into a Morton code.
    12	    ///
    13	    /// Coordinates are first mapped into the non-negative 15-bit integer range
    14	    /// by `(v - min) * inv_size`; C++ `static_cast<int32_t>` truncates toward
    15	    /// zero, which is also what Rust's `as i32` does for in-range values.
    16	    pub fn z_order(&self, x_: f64, y_: f64) -> i32 {
    17	        let mut x: i32 = ((x_ - self.min_x) * self.inv_size) as i32;
    18	        let mut y: i32 = ((y_ - self.min_y) * self.inv_size) as i32;
    19	
    20	        x = (x | x.wrapping_shl(8)) & 0x00FF_00FF;
    21	        x = (x | x.wrapping_shl(4)) & 0x0F0F_0F0F;
    22	        x = (x | x.wrapping_shl(2)) & 0x3333_3333;
    23	        x = (x | x.wrapping_shl(1)) & 0x5555_5555;
    24	
    25	        y = (y | y.wrapping_shl(8)) & 0x00FF_00FF;
    26	        y = (y | y.wrapping_shl(4)) & 0x0F0F_0F0F;
    27	        y = (y | y.wrapping_shl(2)) & 0x3333_3333;
    28	        y = (y | y.wrapping_shl(1)) & 0x5555_5555;
    29	
    30	        x | y.wrapping_shl(1)
    31	    }
    32	
    33	    /// Interlink the ring's nodes into a z-order-sorted list.
    34	    pub fn index_curve(&mut self, start: usize) {
    35	        let mut p = start;
    36	        loop {
    37	            if self.nodes[p].z == 0 {
    38	                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
    39	                self.nodes[p].z = self.z_order(x, y);
    40	            }
    41	            self.nodes[p].prev_z = self.nodes[p].prev;
    42	            self.nodes[p].next_z = self.nodes[p].next;
    43	            p = self.nodes[p].next;
    44	            if p == start {
    45	                break;
    46	            }
    47	        }
    48	
    49	        let tail = self.nodes[p].prev_z;
    50	        self.nodes[tail].next_z = NULL;
    51	        self.nodes[p].prev_z = NULL;
    52	
    53	        self.sort_linked(p);
    54	    }
    55	
    56	    /// Bottom-up merge sort of a doubly-linked list along `prev_z`/`next_z`.
    57	    ///
    58	    /// The `<=` tie-break keeps the sort stable, which the triangulation order
    59	    /// depends on.
    60	    pub fn sort_linked(&mut self, list_in: usize) -> usize {
    61	        let mut list = list_in;
    62	        let mut in_size: i32 = 1;
    63	
    64	        loop {
    65	            let mut p = list;
    66	            list = NULL;
    67	            let mut tail = NULL;
    68	            let mut num_merges = 0;
    69	
    70	            while p != NULL {
    71	                num_merges += 1;
    72	                let mut q = p;
    73	                let mut p_size = 0i32;
    74	                for _ in 0..in_size {
    75	                    p_size += 1;
    76	                    q = self.nodes[q].next_z;
    77	                    if q == NULL {
    78	                        break;
    79	                    }
    80	                }
    81	                let mut q_size = in_size;
    82	
    83	                while p_size > 0 || (q_size > 0 && q != NULL) {
    84	                    let e;
    85	                    if p_size == 0 {
    86	                        e = q;
    87	                        q = self.nodes[q].next_z;
    88	                        q_size -= 1;
    89	                    } else if q_size == 0 || q == NULL {
    90	                        e = p;
    91	                        p = self.nodes[p].next_z;
    92	                        p_size -= 1;
    93	                    } else if self.nodes[p].z <= self.nodes[q].z {
    94	                        e = p;
    95	                        p = self.nodes[p].next_z;
    96	                        p_size -= 1;
    97	                    } else {
    98	                        e = q;
    99	                        q = self.nodes[q].next_z;
   100	                        q_size -= 1;
   101	                    }
   102	
   103	                    if tail != NULL {
   104	                        self.nodes[tail].next_z = e;
   105	                    } else {
   106	                        list = e;
   107	                    }
   108	                    self.nodes[e].prev_z = tail;
   109	                    tail = e;
   110	                }
   111	
   112	                p = q;
   113	            }
   114	
   115	            self.nodes[tail].next_z = NULL;
   116	
   117	            if num_merges <= 1 {
   118	                return list;
   119	            }
   120	            in_size *= 2;
   121	        }
   122	    }
   123	}

  1	//! The ear-clipping core and its three recovery passes.
  2	//!
  3	//! Pass 0 is the plain sweep. If it stalls, pass 1 re-runs after filtering
  4	//! degenerate points, pass 2 cures small local self-intersections, and pass 3
  5	//! (reached as `pass == 2`) splits the remaining polygon along a valid
  6	//! diagonal. Self-intersecting input — which `test19` supplies — spends most
  7	//! of its time in those recovery paths, so their order and index-emission
  8	//! sequence are what determine the output.
  9	
 10	use super::geom::{fmax, fmin, point_in_triangle};
 11	use super::node::NULL;
 12	use super::Earcut;
 13	
 14	impl Earcut {
 15	    /// Build a circular doubly-linked list from a ring, in the requested
 16	    /// winding order.
 17	    pub fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
 18	        let len = points.len();
 19	        let mut last = NULL;
 20	
 21	        // Original winding order of the ring (shoelace sum).
 22	        let mut sum = 0.0f64;
 23	        let mut j = if len > 0 { len - 1 } else { 0 };
 24	        for i in 0..len {
 25	            let p1 = points[i];
 26	            let p2 = points[j];
 27	            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
 28	            j = i;
 29	        }
 30	
 31	        if clockwise == (sum > 0.0) {
 32	            for i in 0..len {
 33	                last = self.insert_node(self.vertices + i, points[i], last);
 34	            }
 35	        } else {
 36	            for i in (0..len).rev() {
 37	                last = self.insert_node(self.vertices + i, points[i], last);
 38	            }
 39	        }
 40	
 41	        if last != NULL {
 42	            let next = self.nodes[last].next;
 43	            if self.equals(last, next) {
 44	                self.remove_node(last);
 45	                last = next;
 46	            }
 47	        }
 48	
 49	        self.vertices += len;
 50	        last
 51	    }
 52	
 53	    /// Append a node after `last` in the ring.
 54	    pub fn insert_node(&mut self, i: usize, pt: [f64; 2], last: usize) -> usize {
 55	        let p = self.nodes.construct(i as u32, pt[0], pt[1]);
 56	
 57	        if last == NULL {
 58	            self.nodes[p].prev = p;
 59	            self.nodes[p].next = p;
 60	        } else {
 61	            let last_next = self.nodes[last].next;
 62	            self.nodes[p].next = last_next;
 63	            self.nodes[p].prev = last;
 64	            self.nodes[last_next].prev = p;
 65	            self.nodes[last].next = p;
 66	        }
 67	
 68	        p
 69	    }
 70	
 71	    /// Unlink `p` from both the ring and the z-order list.
 72	    ///
 73	    /// `p`'s own `prev`/`next` are deliberately left intact: callers walk off a
 74	    /// just-removed node.
 75	    pub fn remove_node(&mut self, p: usize) {
 76	        let next = self.nodes[p].next;
 77	        let prev = self.nodes[p].prev;
 78	        self.nodes[next].prev = prev;
 79	        self.nodes[prev].next = next;
 80	
 81	        let prev_z = self.nodes[p].prev_z;
 82	        let next_z = self.nodes[p].next_z;
 83	        if prev_z != NULL {
 84	            self.nodes[prev_z].next_z = next_z;
 85	        }
 86	        if next_z != NULL {
 87	            self.nodes[next_z].prev_z = prev_z;
 88	        }
 89	    }
 90	
 91	    /// Drop duplicate and collinear vertices between `start` and `end`.
 92	    pub fn filter_points(&mut self, start: usize, end_in: usize) -> usize {
 93	        if start == NULL {
 94	            return NULL;
 95	        }
 96	        let mut end = if end_in == NULL { start } else { end_in };
 97	
 98	        let mut p = start;
 99	        loop {
100	            let mut again = false;
101	
102	            let next = self.nodes[p].next;
103	            let prev = self.nodes[p].prev;
104	            if !self.nodes[p].steiner && (self.equals(p, next) || self.area(prev, p, next) == 0.0) {
105	                self.remove_node(p);
106	                p = self.nodes[p].prev;
107	                end = p;
108	
109	                if p == self.nodes[p].next {
110	                    break;
111	                }
112	                again = true;
113	            } else {
114	                p = next;
115	            }
116	
117	            if !again && p == end {
118	                break;
119	            }
120	        }
121	
122	        end
123	    }
124	
125	    /// Main ear-slicing loop.
126	    pub fn earcut_linked(&mut self, ear_in: usize, pass: i32) {
127	        let mut ear = ear_in;
128	        if ear == NULL {
129	            return;
130	        }
131	
132	        // Interlink polygon nodes in z-order.
133	        if pass == 0 && self.hashing {
134	            self.index_curve(ear);
135	        }
136	
137	        let mut stop = ear;
138	
139	        while self.nodes[ear].prev != self.nodes[ear].next {
140	            let prev = self.nodes[ear].prev;
141	            let next = self.nodes[ear].next;
142	
143	            let is_ear = if self.hashing {
144	                self.is_ear_hashed(ear)
145	            } else {
146	                self.is_ear(ear)
147	            };
148	
149	            if is_ear {
150	                // Cut off the triangle.
151	                self.indices.push(self.nodes[prev].i);
152	                self.indices.push(self.nodes[ear].i);
153	                self.indices.push(self.nodes[next].i);
154	
155	                self.remove_node(ear);
156	
157	                // Skipping the next vertex leads to fewer sliver triangles.
158	                ear = self.nodes[next].next;
159	                stop = self.nodes[next].next;
160	
161	                continue;
162	            }
163	
164	            ear = next;
165	
166	            // Looped through the whole remaining polygon without finding an ear.
167	            if ear == stop {
168	                if pass == 0 {
169	                    // Try filtering points and slicing again.
170	                    let filtered = self.filter_points(ear, NULL);
171	                    self.earcut_linked(filtered, 1);
172	                } else if pass == 1 {
173	                    // Try curing all small self-intersections locally.
174	                    let filtered = self.filter_points(ear, NULL);
175	                    let cured = self.cure_local_intersections(filtered);
176	                    self.earcut_linked(cured, 2);
177	                } else if pass == 2 {
178	                    // Last resort: split the remaining polygon in two.
179	                    self.split_earcut(ear);
180	                }
181	                break;
182	            }
183	        }
184	    }
185	
186	    /// Ear test used while the z-order hash is off.
187	    pub fn is_ear(&self, ear: usize) -> bool {
188	        let a = self.nodes[ear].prev;
189	        let b = ear;
190	        let c = self.nodes[ear].next;
191	
192	        if self.area(a, b, c) >= 0.0 {
193	            return false; // reflex, can't be an ear
194	        }
195	
196	        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
197	        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
198	        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);
199	
200	        // Make sure no other point lies inside the candidate ear.
201	        let ear_prev = self.nodes[ear].prev;
202	        let mut p = self.nodes[self.nodes[ear].next].next;
203	        while p != ear_prev {
204	            if point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
205	                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
206	            {
207	                return false;
208	            }
209	            p = self.nodes[p].next;
210	        }
211	
212	        true
213	    }
214	
215	    /// Ear test accelerated by the z-order curve.
216	    pub fn is_ear_hashed(&self, ear: usize) -> bool {
217	        let a = self.nodes[ear].prev;
218	        let b = ear;
219	        let c = self.nodes[ear].next;
220	
221	        if self.area(a, b, c) >= 0.0 {
222	            return false; // reflex, can't be an ear
223	        }
224	
225	        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
226	        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
227	        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);
228	
229	        // Triangle bbox.
230	        let min_tx = fmin(ax, fmin(bx, cx));
231	        let min_ty = fmin(ay, fmin(by, cy));
232	        let max_tx = fmax(ax, fmax(bx, cx));
233	        let max_ty = fmax(ay, fmax(by, cy));
234	
235	        // Z-order range for that bbox.
236	        let min_z = self.z_order(min_tx, min_ty);
237	        let max_z = self.z_order(max_tx, max_ty);
238	
239	        let ear_prev = self.nodes[ear].prev;
240	        let ear_next = self.nodes[ear].next;
241	
242	        // Points inside the triangle, in increasing z-order.
243	        let mut p = self.nodes[ear].next_z;
244	        while p != NULL && self.nodes[p].z <= max_z {
245	            if p != ear_prev
246	                && p != ear_next
247	                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
248	                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
249	            {
250	                return false;
251	            }
252	            p = self.nodes[p].next_z;
253	        }
254	
255	        // Then in decreasing z-order.
256	        let mut p = self.nodes[ear].prev_z;
257	        while p != NULL && self.nodes[p].z >= min_z {
258	            if p != ear_prev
259	                && p != ear_next
260	                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y)
261	                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
262	            {
263	                return false;
264	            }
265	            p = self.nodes[p].prev_z;
266	        }
267	
268	        true
269	    }
270	
271	    /// Cut off triangles at points where edge `(v[i-1], v[i])` crosses
272	    /// `(v[i+1], v[i+2])`.
273	    pub fn cure_local_intersections(&mut self, start_in: usize) -> usize {
274	        if start_in == NULL {
275	            return NULL;
276	        }
277	        let mut start = start_in;
278	        let mut p = start;
279	
280	        loop {
281	            let a = self.nodes[p].prev;
282	            let pn = self.nodes[p].next;
283	            let b = self.nodes[pn].next;
284	
285	            if !self.equals(a, b)
286	                && self.intersects(a, p, pn, b)
287	                && self.locally_inside(a, b)
288	                && self.locally_inside(b, a)
289	            {
290	                self.indices.push(self.nodes[a].i);
291	                self.indices.push(self.nodes[p].i);
292	                self.indices.push(self.nodes[b].i);
293	
294	                // Remove the two nodes involved.
295	                self.remove_node(p);
296	                let p_next = self.nodes[p].next;
297	                self.remove_node(p_next);
298	
299	                p = b;
300	                start = b;
301	            }
302	
303	            p = self.nodes[p].next;
304	            if p == start {
305	                break;
306	            }
307	        }
308	
309	        self.filter_points(p, NULL)
310	    }
311	
312	    /// Split the polygon along the first valid diagonal and recurse on both
313	    /// halves.
314	    pub fn split_earcut(&mut self, start: usize) {
315	        let mut a = start;
316	        loop {
317	            let mut b = self.nodes[self.nodes[a].next].next;
318	            while b != self.nodes[a].prev {
319	                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
320	                    // Split the polygon in two by the diagonal.
321	                    let mut c = self.split_polygon(a, b);
322	
323	                    // Filter collinear points around the cuts.
324	                    let an = self.nodes[a].next;
325	                    a = self.filter_points(a, an);
326	                    let cn = self.nodes[c].next;
327	                    c = self.filter_points(c, cn);
328	
329	                    // Run earcut on each half.
330	                    self.earcut_linked(a, 0);
331	                    self.earcut_linked(c, 0);
332	                    return;
333	                }
334	                b = self.nodes[b].next;
335	            }
336	            a = self.nodes[a].next;
337	            if a == start {
338	                return;
339	            }
340	        }
341	    }
342	
343	    /// Link two polygon vertices with a bridge, splitting one ring into two
344	    /// (or joining two rings into one).
345	    pub fn split_polygon(&mut self, a: usize, b: usize) -> usize {
346	        let (ai, ax, ay) = (self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
347	        let (bi, bx, by) = (self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
348	
349	        let a2 = self.nodes.construct(ai, ax, ay);
350	        let b2 = self.nodes.construct(bi, bx, by);
351	        let an = self.nodes[a].next;
352	        let bp = self.nodes[b].prev;
353	
354	        self.nodes[a].next = b;
355	        self.nodes[b].prev = a;
356	
357	        self.nodes[a2].next = an;
358	        self.nodes[an].prev = a2;
359	
360	        self.nodes[b2].next = a2;
361	        self.nodes[a2].prev = b2;
362	
363	        self.nodes[bp].next = b2;
364	        self.nodes[b2].prev = bp;
365	
366	        b2
367	    }
368	}

  1	//! Hole elimination: each hole is joined to the outer ring by a bridge
  2	//! diagonal, turning the multi-ring input into a single ring.
  3	//!
  4	//! `test19` feeds a single ring, so none of this runs for that program; it is
  5	//! here so the ported library covers the same surface as `earcut.hpp`.
  6	
  7	use super::node::NULL;
  8	use super::Earcut;
  9	
 10	impl Earcut {
 11	    /// Link every hole into the outer ring, left to right.
 12	    pub fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], outer_node_in: usize) -> usize {
 13	        let mut outer_node = outer_node_in;
 14	
 15	        let mut queue: Vec<usize> = Vec::new();
 16	        for ring in points.iter().skip(1) {
 17	            let list = self.linked_list(ring, false);
 18	            if list != NULL {
 19	                if list == self.nodes[list].next {
 20	                    self.nodes[list].steiner = true;
 21	                }
 22	                queue.push(self.get_leftmost(list));
 23	            }
 24	        }
 25	
 26	        queue.sort_by(|&a, &b| {
 27	            self.nodes[a]
 28	                .x
 29	                .partial_cmp(&self.nodes[b].x)
 30	                .unwrap_or(std::cmp::Ordering::Equal)
 31	        });
 32	
 33	        for &hole in &queue {
 34	            outer_node = self.eliminate_hole(hole, outer_node);
 35	        }
 36	
 37	        outer_node
 38	    }
 39	
 40	    /// Splice a single hole into the outer ring.
 41	    pub fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
 42	        let bridge = self.find_hole_bridge(hole, outer_node);
 43	        if bridge == NULL {
 44	            return outer_node;
 45	        }
 46	
 47	        let bridge_reverse = self.split_polygon(bridge, hole);
 48	
 49	        // Filter collinear points around the cuts.
 50	        let brn = self.nodes[bridge_reverse].next;
 51	        self.filter_points(bridge_reverse, brn);
 52	
 53	        // The bridge node itself may have been filtered away.
 54	        let bn = self.nodes[bridge].next;
 55	        self.filter_points(bridge, bn)
 56	    }
 57	
 58	    /// Find the outer-ring vertex a hole should be bridged to.
 59	    pub fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
 60	        let hx = self.nodes[hole].x;
 61	        let hy = self.nodes[hole].y;
 62	        let mut qx = f64::NEG_INFINITY;
 63	        let mut m = NULL;
 64	
 65	        // Cast a ray to the left from the hole's leftmost vertex; the hit
 66	        // segment's endpoint with the lesser x is the candidate.
 67	        let mut p = outer_node;
 68	        loop {
 69	            let pn = self.nodes[p].next;
 70	            if hy <= self.nodes[p].y && hy >= self.nodes[pn].y && self.nodes[pn].y != self.nodes[p].y
 71	            {
 72	                let x = self.nodes[p].x
 73	                    + (hy - self.nodes[p].y) * (self.nodes[pn].x - self.nodes[p].x)
 74	                        / (self.nodes[pn].y - self.nodes[p].y);
 75	                if x <= hx && x > qx {
 76	                    qx = x;
 77	                    m = if self.nodes[p].x < self.nodes[pn].x {
 78	                        p
 79	                    } else {
 80	                        pn
 81	                    };
 82	                    if x == hx {
 83	                        // The hole touches the outer segment; take the
 84	                        // leftmost endpoint straight away.
 85	                        return m;
 86	                    }
 87	                }
 88	            }
 89	            p = pn;
 90	            if p == outer_node {
 91	                break;
 92	            }
 93	        }
 94	
 95	        if m == NULL {
 96	            return NULL;
 97	        }
 98	
 99	        // Look for vertices inside the triangle formed by the hole vertex, the
100	        // ray hit and the candidate endpoint; if any exist, take the one with
101	        // the minimum angle to the ray instead.
102	        // `mx`/`my` stay pinned to the *initial* candidate, as in the C++
103	        // original — only `m` moves as better candidates are found.
104	        let stop = m;
105	        let mut tan_min = f64::INFINITY;
106	        let mx = self.nodes[m].x;
107	        let my = self.nodes[m].y;
108	
109	        let mut p = m;
110	        loop {
111	            let px = self.nodes[p].x;
112	            let py = self.nodes[p].y;
113	            if hx >= px
114	                && px >= mx
115	                && hx != px
116	                && super::geom::point_in_triangle(
117	                    if hy < my { hx } else { qx },
118	                    hy,
119	                    mx,
120	                    my,
121	                    if hy < my { qx } else { hx },
122	                    hy,
123	                    px,
124	                    py,
125	                )
126	            {
127	                let tan_cur = (hy - py).abs() / (hx - px);
128	
129	                if self.locally_inside(p, hole)
130	                    && (tan_cur < tan_min
131	                        || (tan_cur == tan_min
132	                            && (px > self.nodes[m].x || self.sector_contains_sector(m, p))))
133	                {
134	                    m = p;
135	                    tan_min = tan_cur;
136	                }
137	            }
138	
139	            p = self.nodes[p].next;
140	            if p == stop {
141	                break;
142	            }
143	        }
144	
145	        m
146	    }
147	
148	    /// Leftmost (then lowest) node of a ring.
149	    pub fn get_leftmost(&self, start: usize) -> usize {
150	        let mut leftmost = start;
151	        let mut p = start;
152	        loop {
153	            if self.nodes[p].x < self.nodes[leftmost].x
154	                || (self.nodes[p].x == self.nodes[leftmost].x
155	                    && self.nodes[p].y < self.nodes[leftmost].y)
156	            {
157	                leftmost = p;
158	            }
159	            p = self.nodes[p].next;
160	            if p == start {
161	                return leftmost;
162	            }
163	        }
164	    }
165	}

