        vec![[20.,20.],[20.,22.],[22.,22.],[22.,20.]]]);
    // 12. empty ring among holes
    check("empty hole ring", &vec![
        vec![[0.,0.],[10.,0.],[10.,10.],[0.,10.]],
        vec![], vec![[3.,3.],[3.,7.],[7.,7.],[7.,3.]]]);
    // 13. self-intersecting outer + hole
    check("bowtie+hole", &vec![
        vec![[0.,0.],[10.,10.],[10.,0.],[0.,10.]],
        vec![[4.,4.],[4.,6.],[6.,6.],[6.,4.]]]);
